package com.example.csvpointbypointbatch.batch;
import org.springframework.batch.item.Chunk;import org.springframework.batch.item.ItemWriter;import org.springframework.jdbc.core.JdbcTemplate;
public class ResultsWriter implements ItemWriter<ResultRow>{static final String SQL="INSERT INTO point_by_point_event(match_id,quarter,sequence,record_type,home_score,away_score,home_points_added,away_points_added,leader_side,advantage,advantage_direction,home_is_winning,away_is_winning) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(match_id,quarter,sequence) DO UPDATE SET record_type=EXCLUDED.record_type,home_score=EXCLUDED.home_score,away_score=EXCLUDED.awAY_score,home_points_added=EXCLUDED.home_points_added,away_points_added=EXCLUDED.away_points_added,leader_side=EXCLUDED.leader_side,advantage=EXCLUDED.advantage,advantage_direction=EXCLUDED.advantage_direction,home_is_winning=EXCLUDED.home_is_winning,away_is_winning=EXCLUDED.away_is_winning";private final JdbcTemplate jdbc;public ResultsWriter(JdbcTemplate j,String ignored){jdbc=j;}public void write(Chunk<? extends ResultRow> c){jdbc.batchUpdate(SQL,c.getItems(),c.size(),(s,r)->{String[]v=r.v();s.setObject(1,v[0]);s.setObject(2,v[2]);s.setObject(3,Integer.valueOf(v[3]));s.setObject(4,v[1]);for(int i=4;i<=7;i++)s.setObject(i+1,Integer.valueOf(v[i]));s.setObject(9,v[8]);s.setObject(10,v[9]);s.setObject(11,v[10]);s.setObject(12,Boolean.valueOf(v[11]));s.setObject(13,Boolean.valueOf(v[12]));});}}
